import type { LogEntry, WorkflowRunState } from '../../types';

// ─── Develop renderer types ─────────────────────────────────────────────────

export interface DevelopPhaseInfo {
  id: string;
  label: string;
  icon: string;
  status: 'completed' | 'active' | 'pending';
}

export interface DevelopAgentInfo {
  agentId: string;
  profile: string;
  taskId?: string;
  active: boolean;
  log: LogEntry[];
}

export interface DevelopRendererState {
  phases: DevelopPhaseInfo[];
  agents: DevelopAgentInfo[];
  currentPhase: string;
}

// ─── Helper ─────────────────────────────────────────────────────────────────

export function buildDevelopState(runState: WorkflowRunState): DevelopRendererState {
  const phases: DevelopPhaseInfo[] = [];
  const sidebarPhases = runState.summary.sidebar.phases;
  if (sidebarPhases) {
    for (const phase of sidebarPhases) {
      let status: 'completed' | 'active' | 'pending';
      if (runState.completedPhases.includes(phase.id)) {
        status = 'completed';
      } else if (phase.id === runState.currentPhase) {
        status = 'active';
      } else {
        status = 'pending';
      }
      phases.push({
        id: phase.id,
        label: phase.label,
        icon: phase.icon,
        status,
      });
    }
  }

  const agents: DevelopAgentInfo[] = [];
  for (const [agentId, agent] of runState.agents) {
    agents.push({
      agentId: agent.agentId,
      profile: agent.profile,
      taskId: agent.taskId,
      active: agent.active,
      log: agent.log,
    });
  }
  agents.sort((a, b) => a.agentId.localeCompare(b.agentId));

  return {
    phases,
    agents,
    currentPhase: runState.currentPhase,
  };
}

/**
 * Tests for develop renderer types and the buildDevelopState helper.
 */

import { describe, it, expect } from 'vitest';

import type {
  WorkflowRunState,
  WorkflowSummary,
  AgentWindowState,
  PhaseDescriptor,
  LogEntry,
} from '../../../types';
import { buildDevelopState } from '../types';
import type {
  DevelopPhaseInfo,
  DevelopAgentInfo,
  DevelopRendererState,
} from '../types';

// ─── Helpers ────────────────────────────────────────────────────────────────

function createPhase(id: string, label?: string, icon?: string): PhaseDescriptor {
  return { id, label: label ?? id, icon: icon ?? '🔵' };
}

function createAgentWindow(agentId: string, overrides: Partial<AgentWindowState> = {}): AgentWindowState {
  return {
    agentId,
    profile: 'default',
    active: false,
    log: [],
    ...overrides,
  };
}

function createSummary(overrides: Partial<WorkflowSummary> = {}): WorkflowSummary {
  const sidebar = overrides.sidebar ?? {
    title: 'Test',
    indicator: '…',
    phases: [],
  };
  return {
    id: 'test-run',
    workflowName: 'Test Workflow',
    status: 'running',
    startedAt: new Date().toISOString(),
    ...overrides,
    sidebar,
  };
}

function createRunState(overrides: Partial<WorkflowRunState> = {}): WorkflowRunState {
  return {
    summary: createSummary(),
    agents: new Map(),
    currentPhase: '',
    completedPhases: [],
    ...overrides,
  };
}

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('buildDevelopState', () => {
  describe('phases', () => {
    it('should return empty phases array when sidebar has no phases', () => {
      const summary = createSummary({ sidebar: { title: 'No phases', indicator: '…' } });
      const state = createRunState({ summary });
      const result = buildDevelopState(state);
      expect(result.phases).toEqual([]);
    });

    it('should return empty phases array when sidebar.phases is undefined', () => {
      const summary = createSummary({ sidebar: { title: 'No phases', indicator: '…', phases: undefined } });
      const state = createRunState({ summary });
      const result = buildDevelopState(state);
      expect(result.phases).toEqual([]);
    });

    it('should mark a phase as completed when its id is in completedPhases', () => {
      const phases: PhaseDescriptor[] = [
        createPhase('phase-1', 'Phase 1', '📋'),
        createPhase('phase-2', 'Phase 2', '⚙️'),
      ];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'phase-2',
        completedPhases: ['phase-1'],
      });
      const result = buildDevelopState(state);
      expect(result.phases).toHaveLength(2);
      expect(result.phases[0].status).toBe('completed');
      expect(result.phases[1].status).toBe('active');
    });

    it('should mark a phase as active when it equals currentPhase and is not in completedPhases', () => {
      const phases: PhaseDescriptor[] = [
        createPhase('phase-1'),
        createPhase('phase-2'),
        createPhase('phase-3'),
      ];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'phase-2',
        completedPhases: ['phase-1'],
      });
      const result = buildDevelopState(state);
      expect(result.phases[0].status).toBe('completed');
      expect(result.phases[1].status).toBe('active');
      expect(result.phases[2].status).toBe('pending');
    });

    it('should mark a phase as pending when it is neither completed nor active', () => {
      const phases: PhaseDescriptor[] = [
        createPhase('phase-1'),
        createPhase('phase-2'),
        createPhase('phase-3'),
      ];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'phase-1',
        completedPhases: [],
      });
      const result = buildDevelopState(state);
      expect(result.phases[0].status).toBe('active');
      expect(result.phases[1].status).toBe('pending');
      expect(result.phases[2].status).toBe('pending');
    });

    it('should prefer completed status over active when phase is in both completedPhases and currentPhase', () => {
      const phases: PhaseDescriptor[] = [createPhase('phase-1')];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'phase-1',
        completedPhases: ['phase-1'],
      });
      const result = buildDevelopState(state);
      expect(result.phases[0].status).toBe('completed');
    });

    it('should preserve id, label, and icon from PhaseDescriptor', () => {
      const phases: PhaseDescriptor[] = [
        { id: 'research', label: 'Research', icon: '🔍' },
        { id: 'implement', label: 'Implement', icon: '⚙️' },
      ];
      const summary = createSummary({ sidebar: { title: 'Test', indicator: '…', phases } });
      const state = createRunState({
        summary,
        currentPhase: 'implement',
        completedPhases: ['research'],
      });
      const result = buildDevelopState(state);
      expect(result.phases[0]).toEqual({
        id: 'research',
        label: 'Research',
        icon: '🔍',
        status: 'completed',
      });
      expect(result.phases[1]).toEqual({
        id: 'implement',
        label: 'Implement',
        icon: '⚙️',
        status: 'active',
      });
    });
  });

  describe('agents', () => {
    it('should return empty agents array when runState has no agents', () => {
      const state = createRunState({ agents: new Map() });
      const result = buildDevelopState(state);
      expect(result.agents).toEqual([]);
    });

    it('should convert agents Map to sorted array by agentId', () => {
      const agents = new Map<string, AgentWindowState>([
        ['agent-beta', createAgentWindow('agent-beta', { profile: 'beta', active: true })],
        ['agent-alpha', createAgentWindow('agent-alpha', { profile: 'alpha', active: false })],
        ['agent-gamma', createAgentWindow('agent-gamma', { profile: 'gamma', active: true })],
      ]);
      const state = createRunState({ agents });
      const result = buildDevelopState(state);
      expect(result.agents).toHaveLength(3);
      expect(result.agents[0].agentId).toBe('agent-alpha');
      expect(result.agents[1].agentId).toBe('agent-beta');
      expect(result.agents[2].agentId).toBe('agent-gamma');
    });

    it('should include all agent properties', () => {
      const logEntry: LogEntry = {
        id: 'log-1',
        timestamp: new Date().toISOString(),
        type: 'text',
        content: 'hello',
      };
      const agent = createAgentWindow('agent-1', {
        profile: 'worker',
        taskId: 'task-42',
        active: true,
        log: [logEntry],
      });
      const agents = new Map([['agent-1', agent]]);
      const state = createRunState({ agents });
      const result = buildDevelopState(state);
      expect(result.agents[0]).toEqual({
        agentId: 'agent-1',
        profile: 'worker',
        taskId: 'task-42',
        active: true,
        log: [logEntry],
      });
    });

    it('should handle agents without taskId', () => {
      const agent = createAgentWindow('agent-1', {
        profile: 'solo',
        active: false,
        taskId: undefined,
      });
      const agents = new Map([['agent-1', agent]]);
      const state = createRunState({ agents });
      const result = buildDevelopState(state);
      expect(result.agents[0].taskId).toBeUndefined();
    });

    it('should preserve log entries array order', () => {
      const entry1: LogEntry = { id: '1', timestamp: '2024-01-01T00:00:00Z', type: 'text', content: 'first' };
      const entry2: LogEntry = { id: '2', timestamp: '2024-01-01T00:00:01Z', type: 'text', content: 'second' };
      const entry3: LogEntry = { id: '3', timestamp: '2024-01-01T00:00:02Z', type: 'text', content: 'third' };
      const agent = createAgentWindow('agent-1', {
        log: [entry1, entry2, entry3],
      });
      const agents = new Map([['agent-1', agent]]);
      const state = createRunState({ agents });
      const result = buildDevelopState(state);
      expect(result.agents[0].log).toEqual([entry1, entry2, entry3]);
    });
  });

  describe('currentPhase', () => {
    it('should return the currentPhase from runState', () => {
      const state = createRunState({ currentPhase: 'phase-3' });
      const result = buildDevelopState(state);
      expect(result.currentPhase).toBe('phase-3');
    });

    it('should return empty string when currentPhase is empty', () => {
      const state = createRunState({ currentPhase: '' });
      const result = buildDevelopState(state);
      expect(result.currentPhase).toBe('');
    });
  });

  describe('integration', () => {
    it('should produce correct DevelopRendererState from a realistic WorkflowRunState', () => {
      const phases: PhaseDescriptor[] = [
        { id: 'plan', label: 'Plan', icon: '📋' },
        { id: 'code', label: 'Code', icon: '💻' },
        { id: 'test', label: 'Test', icon: '🧪' },
        { id: 'deploy', label: 'Deploy', icon: '🚀' },
      ];

      const logA: LogEntry[] = [
        { id: 'a1', timestamp: '2024-01-01T00:00:00Z', type: 'text', content: 'Starting' },
      ];
      const logB: LogEntry[] = [
        { id: 'b1', timestamp: '2024-01-01T00:00:05Z', type: 'thinking', content: 'Thinking...' },
        { id: 'b2', timestamp: '2024-01-01T00:00:06Z', type: 'decision', content: 'Decided' },
      ];

      const agents = new Map<string, AgentWindowState>([
        [
          'planner',
          {
            agentId: 'planner',
            profile: 'Planner Agent',
            taskId: 'task-plan',
            active: false,
            log: logA,
          },
        ],
        [
          'coder',
          {
            agentId: 'coder',
            profile: 'Coder Agent',
            taskId: 'task-code',
            active: true,
            log: logB,
          },
        ],
      ]);

      const summary = createSummary({
        id: 'run-integration',
        workflowName: 'Build Feature',
        status: 'running',
        sidebar: {
          title: 'Build Feature',
          indicator: '…',
          phases,
        },
        startedAt: '2024-01-01T00:00:00Z',
      });

      const runState: WorkflowRunState = {
        summary,
        agents,
        currentPhase: 'code',
        completedPhases: ['plan'],
      };

      const result = buildDevelopState(runState);

      // Verify phases
      expect(result.phases).toHaveLength(4);
      expect(result.phases[0]).toEqual({ id: 'plan', label: 'Plan', icon: '📋', status: 'completed' });
      expect(result.phases[1]).toEqual({ id: 'code', label: 'Code', icon: '💻', status: 'active' });
      expect(result.phases[2]).toEqual({ id: 'test', label: 'Test', icon: '🧪', status: 'pending' });
      expect(result.phases[3]).toEqual({ id: 'deploy', label: 'Deploy', icon: '🚀', status: 'pending' });

      // Verify agents (sorted by agentId: coder before planner)
      expect(result.agents).toHaveLength(2);
      expect(result.agents[0].agentId).toBe('coder');
      expect(result.agents[0].profile).toBe('Coder Agent');
      expect(result.agents[0].taskId).toBe('task-code');
      expect(result.agents[0].active).toBe(true);
      expect(result.agents[0].log).toEqual(logB);

      expect(result.agents[1].agentId).toBe('planner');
      expect(result.agents[1].profile).toBe('Planner Agent');
      expect(result.agents[1].taskId).toBe('task-plan');
      expect(result.agents[1].active).toBe(false);
      expect(result.agents[1].log).toEqual(logA);

      // Verify currentPhase
      expect(result.currentPhase).toBe('code');
    });
  });
});

/**
 * Tests for useWebSocket hook.
 *
 * We mock WebSocket and window.__WS_ENDPOINT__ to control the connection
 * and simulate server messages without a real server.
 */

import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest';
import { renderHook, act } from '@testing-library/react';

// ─── Types we need ──────────────────────────────────────────────────────────
import type {
  ClientMessage,
  ServerMessage,
  WorkflowSummary,
  AgentWindowState,
  LogEntry,
  SidebarInfo,
} from '../../types';

// ─── Module under test ──────────────────────────────────────────────────────
import { useWebSocket } from '../useWebSocket';

// ─── Helpers ────────────────────────────────────────────────────────────────

function createMockSummary(overrides: Partial<WorkflowSummary> = {}): WorkflowSummary {
  return {
    id: 'test-run-1',
    workflowName: 'Test Workflow',
    status: 'running',
    sidebar: { title: 'Test', indicator: '…' },
    startedAt: new Date().toISOString(),
    ...overrides,
  };
}

// ─── WebSocket mock ─────────────────────────────────────────────────────────

// We use a class so that `new MockWebSocket(url)` works as a constructor.
class MockWebSocket {
  static CONNECTING = 0;
  static OPEN = 1;
  static CLOSING = 2;
  static CLOSED = 3;

  static instances: MockWebSocket[] = [];

  url: string;
  readyState: number;

  onopen: ((event: Event) => void) | null = null;
  onclose: ((event: CloseEvent) => void) | null = null;
  onerror: ((event: Event) => void) | null = null;
  onmessage: ((event: MessageEvent) => void) | null = null;

  // Store listeners for test-triggered events
  private _openListeners: Set<() => void> = new Set();
  private _closeListeners: Set<(code?: number, reason?: string) => void> = new Set();
  private _errorListeners: Set<() => void> = new Set();
  private _messageListeners: Set<(data: ServerMessage) => void> = new Set();

  // Spies for verifying calls
  send = vi.fn<(data: string) => void>();
  close = vi.fn(() => {
    this.readyState = MockWebSocket.CLOSED;
    this._closeListeners.forEach((fn) => fn(1000, 'normal'));
  });

  constructor(url: string) {
    this.url = url;
    this.readyState = MockWebSocket.CONNECTING;

    // Track all instances
    MockWebSocket.instances.push(this);
    // Store reference globally so tests can interact with this instance
    (globalThis as any).__currentMockWs = this;
  }

  /** Register event listeners (used by testing-library or DOM env) */
  addEventListener(type: string, fn: EventListenerOrEventListenerObject): void {
    if (type === 'open') this._openListeners.add(fn as unknown as () => void);
    else if (type === 'close') this._closeListeners.add(fn as unknown as (code?: number, reason?: string) => void);
    else if (type === 'error') this._errorListeners.add(fn as unknown as () => void);
    else if (type === 'message') this._messageListeners.add(fn as unknown as (data: ServerMessage) => void);
  }

  removeEventListener(type: string, fn: EventListenerOrEventListenerObject): void {
    if (type === 'open') this._openListeners.delete(fn as unknown as () => void);
    else if (type === 'close') this._closeListeners.delete(fn as unknown as (code?: number, reason?: string) => void);
    else if (type === 'error') this._errorListeners.delete(fn as unknown as () => void);
    else if (type === 'message') this._messageListeners.delete(fn as unknown as (data: ServerMessage) => void);
  }

  // ── Test helpers ──────────────────────────────────────────────────────────

  _triggerOpen(): void {
    this.readyState = MockWebSocket.OPEN;
    this._openListeners.forEach((fn) => fn());
    if (this.onopen) this.onopen(new Event('open'));
  }

  _triggerClose(code = 1000, reason = ''): void {
    this.readyState = MockWebSocket.CLOSED;
    this._closeListeners.forEach((fn) => fn(code, reason));
    if (this.onclose) this.onclose(new CloseEvent('close', { code, reason, wasClean: true }));
  }

  _triggerError(): void {
    this._errorListeners.forEach((fn) => fn());
    if (this.onerror) this.onerror(new Event('error'));
  }

  _triggerMessage(data: ServerMessage): void {
    const json = JSON.stringify(data);
    const event = new MessageEvent('message', { data: json });
    this._messageListeners.forEach((fn) => fn(data));
    if (this.onmessage) this.onmessage(event);
  }
}

/** Convenience accessor for the current mock WebSocket in tests */
function getMockWs(): MockWebSocket {
  const ws = (globalThis as any).__currentMockWs;
  if (!ws) throw new Error('No MockWebSocket instance exists. Did the hook mount?');
  return ws;
}

// ─── Globals ─────────────────────────────────────────────────────────────────

const originalWebSocket = globalThis.WebSocket;

// ─── Setup / Teardown ────────────────────────────────────────────────────────

beforeEach(() => {
  (globalThis as any).__currentMockWs = null;
  MockWebSocket.instances = [];
  globalThis.WebSocket = MockWebSocket as unknown as typeof globalThis.WebSocket;
});

afterEach(() => {
  globalThis.WebSocket = originalWebSocket;
  delete (globalThis as any).__currentMockWs;
  delete (window as any).__WS_ENDPOINT__;
});

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('useWebSocket', () => {
  it('should connect to default dev endpoint on mount', () => {
    const { unmount } = renderHook(() => useWebSocket());
    const ws = getMockWs();
    expect(ws.url).toBe('ws://localhost:3619/ws');
    expect(ws.readyState).toBe(MockWebSocket.CONNECTING);
    unmount();
  });

  it('should use __WS_ENDPOINT__ when set (production)', () => {
    (window as any).__WS_ENDPOINT__ = 'wss://example.com/ws';
    const { unmount } = renderHook(() => useWebSocket());
    const ws = getMockWs();
    expect(ws.url).toBe('wss://example.com/ws');
    unmount();
  });

  it('should set connected=true after WebSocket opens', () => {
    const { result, unmount } = renderHook(() => useWebSocket());
    expect(result.current.connected).toBe(false);
    act(() => {
      getMockWs()._triggerOpen();
    });
    expect(result.current.connected).toBe(true);
    unmount();
  });

  it('should close WebSocket on unmount', () => {
    const { unmount } = renderHook(() => useWebSocket());
    const ws = getMockWs();
    expect(ws.close).not.toHaveBeenCalled();
    unmount();
    expect(ws.close).toHaveBeenCalled();
  });

  it('should send JSON-stringified messages via send()', () => {
    const { result, unmount } = renderHook(() => useWebSocket());
    act(() => {
      getMockWs()._triggerOpen();
    });
    const msg: ClientMessage = {
      type: 'start_workflow',
      workflowName: 'test',
      taskPrompt: 'do stuff',
    };
    act(() => {
      result.current.send(msg);
    });
    expect(getMockWs().send).toHaveBeenCalledWith(JSON.stringify(msg));
    unmount();
  });

  it('should update selectedRunId and send select_workflow on selectRun()', () => {
    const { result, unmount } = renderHook(() => useWebSocket());
    act(() => {
      getMockWs()._triggerOpen();
    });
    act(() => {
      result.current.selectRun('run-42');
    });
    expect(result.current.state.selectedRunId).toBe('run-42');
    const expectedMsg: ClientMessage = { type: 'select_workflow', workflowId: 'run-42' };
    expect(getMockWs().send).toHaveBeenCalledWith(JSON.stringify(expectedMsg));
    unmount();
  });

  it('should handle init message', () => {
    const { result, unmount } = renderHook(() => useWebSocket());
    const workflows: WorkflowSummary[] = [
      createMockSummary({ id: 'w1', workflowName: 'Alpha' }),
      createMockSummary({ id: 'w2', workflowName: 'Beta' }),
    ];
    act(() => {
      getMockWs()._triggerMessage({ type: 'init', workflows });
    });
    expect(result.current.state.workflows).toEqual(workflows);
    unmount();
  });

  it('should handle workflow_started message', () => {
    const { result, unmount } = renderHook(() => useWebSocket());
    const summary = createMockSummary({ id: 'w-new' });
    act(() => {
      getMockWs()._triggerMessage({ type: 'workflow_started', summary });
    });
    expect(result.current.state.workflows).toContainEqual(summary);
    expect(result.current.state.runStates.has('w-new')).toBe(true);
    const runState = result.current.state.runStates.get('w-new');
    expect(runState?.summary).toEqual(summary);
    expect(runState?.agents).toBeInstanceOf(Map);
    unmount();
  });

  it('should handle workflow_sidebar message', () => {
    const { result, unmount } = renderHook(() => useWebSocket());
    const summary = createMockSummary({
      id: 'w-side',
      sidebar: { title: 'Old', indicator: '…' },
    });
    act(() => {
      getMockWs()._triggerMessage({ type: 'init', workflows: [summary] });
    });
    const newSidebar: SidebarInfo = { title: 'New Title', indicator: '✓' };
    act(() => {
      getMockWs()._triggerMessage({
        type: 'workflow_sidebar',
        workflowId: 'w-side',
        sidebar: newSidebar,
      });
    });
    const updated = result.current.state.workflows.find((w) => w.id === 'w-side');
    expect(updated?.sidebar).toEqual(newSidebar);
    unmount();
  });

  it('should handle workflow_phase message', () => {
    const { result, unmount } = renderHook(() => useWebSocket());
    const summary = createMockSummary({ id: 'w-phase' });
    act(() => {
      getMockWs()._triggerMessage({ type: 'workflow_started', summary });
    });
    act(() => {
      getMockWs()._triggerMessage({
        type: 'workflow_phase',
        workflowId: 'w-phase',
        phase: 'phase-2',
        completed: ['phase-1'],
      });
    });
    const runState = result.current.state.runStates.get('w-phase');
    expect(runState?.currentPhase).toBe('phase-2');
    expect(runState?.completedPhases).toEqual(['phase-1']);
    unmount();
  });

  it('should handle workflow_complete message', () => {
    const { result, unmount } = renderHook(() => useWebSocket());
    const summary = createMockSummary({ id: 'w-done', status: 'running' });
    act(() => {
      getMockWs()._triggerMessage({ type: 'init', workflows: [summary] });
    });
    const completedSummary = createMockSummary({
      id: 'w-done',
      status: 'completed',
      completedAt: new Date().toISOString(),
    });
    act(() => {
      getMockWs()._triggerMessage({ type: 'workflow_complete', summary: completedSummary });
    });
    const updated = result.current.state.workflows.find((w) => w.id === 'w-done');
    expect(updated?.status).toBe('completed');
    expect(updated?.completedAt).toBe(completedSummary.completedAt);
    unmount();
  });

